const rawUrl = String(
  $json['University Homepage URL'] ?? ''
).trim();

const targetField = String(
  $json['Target Field'] ?? ''
).trim();

const country = String(
  $json['Country'] ?? ''
).trim();

const degreeLevel = String(
  $json['Degree Level'] ?? ''
).trim();

// --------------------------------------------------
// 1. Validate required inputs
// --------------------------------------------------

if (
  !rawUrl ||
  !targetField ||
  !country ||
  !degreeLevel
) {
  throw new Error(
    'One or more required discovery inputs are missing.'
  );
}


// --------------------------------------------------
// 2. Normalize university homepage URL
// --------------------------------------------------

let normalizedUrl = rawUrl;

if (!/^https?:\/\//i.test(normalizedUrl)) {
  normalizedUrl = `https://${normalizedUrl}`;
}


// --------------------------------------------------
// 3. Basic URL validation
// --------------------------------------------------

const urlMatch = normalizedUrl.match(
  /^(https?):\/\/([^/?#\s]+)(\/[^?#\s]*)?(?:\?[^#\s]*)?(?:#\S*)?$/i
);

if (!urlMatch) {
  throw new Error(
    'University Homepage URL is invalid.'
  );
}


// --------------------------------------------------
// 4. Extract URL components
// --------------------------------------------------

const protocol = urlMatch[1].toLowerCase();

const host = urlMatch[2].toLowerCase();

const pathname = urlMatch[3] || '';

const hostname = host
  .split(':')[0]
  .toLowerCase();


// --------------------------------------------------
// 5. Validate domain
// --------------------------------------------------

const domainWithoutWww = hostname.replace(/^www\./, '');

const domainPattern =
  /^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z0-9-]{2,63}$/i;

if (!domainPattern.test(domainWithoutWww)) {
  throw new Error(
    'University Homepage URL contains an invalid domain.'
  );
}


// --------------------------------------------------
// 6. Remove query parameters, fragments,
//    and unnecessary trailing slash
// --------------------------------------------------

normalizedUrl =
  `${protocol}://${host}${pathname}`
    .replace(/\/+$/, '');


// --------------------------------------------------
// 7. Set official domain
// --------------------------------------------------

const officialDomain = domainWithoutWww;


// --------------------------------------------------
// 8. Return normalized production data
// --------------------------------------------------

return {
  json: {
    university_homepage_url: normalizedUrl,
    official_domain: officialDomain,
    target_field: targetField,
    country: country,
    degree_level: degreeLevel
  }
};

