parameters.jsCode:
const verification =
  $('Verify Official University Website')
    .first()
    .json;

const universityName = String(
  verification?.data?.json?.university_name || ''
).trim();

const source = $('Normalize & Validate Input').first().json;

const targetField = String(source.target_field || '').trim();
const degreeLevel = String(source.degree_level || '').trim();

if (!targetField || !degreeLevel) {
  throw new Error('Target field or degree level is missing.');
}

const normalizedDegree = degreeLevel.toLowerCase();

let primaryDegreeTerm = degreeLevel;
let alternateDegreeTerm = degreeLevel;

if (
  normalizedDegree === 'phd' ||
  normalizedDegree === 'ph.d' ||
  normalizedDegree === 'doctorate'
) {
  primaryDegreeTerm = 'PhD';
  alternateDegreeTerm = 'doctoral';
}

if (
  normalizedDegree === 'master' ||
  normalizedDegree === 'masters'
) {
  primaryDegreeTerm = 'Master';
  alternateDegreeTerm = 'graduate';
}

if (
  normalizedDegree === 'bachelor' ||
  normalizedDegree === 'bachelors'
) {
  primaryDegreeTerm = 'Bachelor';
  alternateDegreeTerm = 'undergraduate';
}

const queries = [
  {
    query_index: 1,
    query_type: 'degree_program',
    search_query: `"${targetField}" "${primaryDegreeTerm}"`
  },
  {
    query_index: 2,
    query_type: 'alternate_degree_program',
    search_query: `"${targetField}" "${alternateDegreeTerm}"`
  },
  {
    query_index: 3,
    query_type: 'department',
    search_query: `"${targetField}" department`
  }
];

return queries.map(query => ({
  json: {
    ...source,

    university_name:
      universityName,

    ...query
  }
}));

const source = $('Normalize & Validate Input').first().json;

const officialDomain = String(source.official_domain || '')
  .trim()
  .toLowerCase()
  .replace(/^www\./, '')
  .replace(/\/+$/, '');

if (!officialDomain) {
  throw new Error('Official domain is missing.');
}

const responses = $input.all();
const queryItems = $('Build Targeted Program Search Queries').all();

const candidates = [];
const seenUrls = new Set();

let rawSearchResultCount = 0;


// =====================================
// LOOP THROUGH ALL 3 SEARCH RESPONSES
// =====================================

for (let i = 0; i < responses.length; i++) {

  const response = responses[i].json || {};

  const results = Array.isArray(response?.data?.web)
    ? response.data.web
    : [];

  rawSearchResultCount += results.length;

  const queryInfo = queryItems[i]?.json || {};

  for (const result of results) {

    const rawUrl = String(result?.url || '').trim();

    if (!rawUrl) {
      continue;
    }


    // =====================================
    // EXTRACT HOST WITHOUT new URL()
    // =====================================

    const hostMatch = rawUrl.match(
      /^https?:\/\/([^\/?#]+)/i
    );

    if (!hostMatch) {
      continue;
    }

    const candidateHost = hostMatch[1]
      .toLowerCase()
      .replace(/^www\./, '')
      .split(':')[0];


    // =====================================
    // VERIFY OFFICIAL UNIVERSITY DOMAIN
    // =====================================

    const isOfficialDomain =
      candidateHost === officialDomain ||
      candidateHost.endsWith('.' + officialDomain);

    if (!isOfficialDomain) {
      continue;
    }


    // =====================================
    // CLEAN URL
    // =====================================

    let cleanUrl = rawUrl
      .split('#')[0]
      .split('?')[0]
      .replace(/\/+$/, '');

    if (!cleanUrl) {
      continue;
    }


    // =====================================
    // REMOVE DUPLICATES
    // =====================================

    const dedupeKey = cleanUrl
      .toLowerCase()
      .replace(/^https?:\/\/www\./, 'https://');

    if (seenUrls.has(dedupeKey)) {
      continue;
    }

    seenUrls.add(dedupeKey);


    // =====================================
    // ADD CANDIDATE
    // =====================================

    candidates.push({

      university_homepage_url:
        source.university_homepage_url,

      official_domain:
        officialDomain,

      target_field:
        source.target_field,

      country:
        source.country,

      degree_level:
        source.degree_level,

      candidate_url:
        cleanUrl,

      candidate_title:
        String(result?.title || '').trim(),

      candidate_description:
        String(result?.description || '').trim(),

      candidate_position:
        Number(result?.position || 999),

      candidate_domain:
        candidateHost,

      official_domain_match:
        true,

      discovered_by_query_index:
        queryInfo.query_index || i + 1,

      discovered_by_query_type:
        queryInfo.query_type || 'unknown',

      discovered_by_query:
        queryInfo.search_query || ''
    });
  }
}


// =====================================
// NO CANDIDATES
// =====================================

if (candidates.length === 0) {

  return [
    {
      json: {
        ...source,

        program_candidates_found: false,

        candidate_count: 0,

        raw_search_result_count:
          rawSearchResultCount,

        search_response_count:
          responses.length,

        normalization_status:
          'no_official_domain_candidates'
      }
    }
  ];
}


// =====================================
// SORT
// =====================================

candidates.sort((a, b) => {

  if (
    a.discovered_by_query_index !==
    b.discovered_by_query_index
  ) {
    return (
      a.discovered_by_query_index -
      b.discovered_by_query_index
    );
  }

  return (
    a.candidate_position -
    b.candidate_position
  );
});


// =====================================
// LIMIT TO 15
// =====================================

const finalCandidates =
  candidates.slice(0, 15);

const candidateCount =
  finalCandidates.length;


// =====================================
// OUTPUT
// =====================================

return finalCandidates.map(
  (candidate, index) => ({
    json: {

      ...candidate,

      program_candidates_found:
        true,

      candidate_number:
        index + 1,

      candidate_count:
        candidateCount,

      raw_search_result_count:
        rawSearchResultCount,

      search_response_count:
        responses.length,

      normalization_status:
        'success'
    }
  })
);

// =============================================
// 09 — Rank Program / Department Candidates
// n8n 2.35.7
// =============================================

const items = $input.all();

if (items.length === 0) {
  throw new Error('No input received from Node 08.');
}


// =============================================
// HANDLE "NO CANDIDATES" SENTINEL
// =============================================

if (
  items.length === 1 &&
  items[0].json.program_candidates_found === false
) {
  return [
    {
      json: {
        ...items[0].json,
        ranked_candidates_found: false,
        ranking_status: 'no_candidates_to_rank'
      }
    }
  ];
}


const source = items[0].json;

const targetField = String(
  source.target_field || ''
).trim().toLowerCase();

const degreeLevel = String(
  source.degree_level || ''
).trim().toLowerCase();


// =============================================
// DEGREE ALIASES
// =============================================

let degreeAliases = [];

if (
  degreeLevel === 'master' ||
  degreeLevel === 'masters' ||
  degreeLevel.includes('master')
) {
  degreeAliases = [
    'master',
    'masters',
    "master's",
    'msc',
    'm.sc'
  ];
}

else if (
  degreeLevel === 'phd' ||
  degreeLevel.includes('doctor')
) {
  degreeAliases = [
    'phd',
    'ph.d',
    'doctoral',
    'doctorate',
    'doctor of philosophy'
  ];
}

else if (
  degreeLevel === 'bachelor' ||
  degreeLevel === 'bachelors' ||
  degreeLevel.includes('bachelor')
) {
  degreeAliases = [
    'bachelor',
    'bachelors',
    "bachelor's",
    'bsc',
    'b.sc',
    'undergraduate'
  ];
}


// =============================================
// SCORING FUNCTION
// =============================================

function scoreCandidate(candidate) {

  const title = String(
    candidate.candidate_title || ''
  ).toLowerCase();

  const description = String(
    candidate.candidate_description || ''
  ).toLowerCase();

  const url = String(
    candidate.candidate_url || ''
  ).toLowerCase();

  const queryType = String(
    candidate.discovered_by_query_type || ''
  ).toLowerCase();

  let score = 0;
  const reasons = [];


  // -----------------------------------------
  // TARGET FIELD MATCH
  // -----------------------------------------

  if (
    targetField &&
    title.includes(targetField)
  ) {
    score += 35;
    reasons.push('target_field_in_title');
  }

  else if (
    targetField &&
    description.includes(targetField)
  ) {
    score += 15;
    reasons.push('target_field_in_description');
  }


  // -----------------------------------------
  // DEGREE MATCH
  // -----------------------------------------

  const degreeInTitle =
    degreeAliases.some(term =>
      title.includes(term)
    );

  const degreeInDescription =
    degreeAliases.some(term =>
      description.includes(term)
    );

  if (degreeInTitle) {
    score += 30;
    reasons.push('degree_match_in_title');
  }

  else if (degreeInDescription) {
    score += 10;
    reasons.push('degree_match_in_description');
  }


  // -----------------------------------------
  // QUERY TYPE PRIORITY
  // -----------------------------------------

  if (queryType === 'degree_program') {
    score += 15;
    reasons.push('degree_program_query');
  }

  else if (
    queryType === 'alternate_degree_program'
  ) {
    score += 10;
    reasons.push('alternate_degree_query');
  }

  else if (queryType === 'department') {
    score += 6;
    reasons.push('department_query');
  }


  // -----------------------------------------
  // STRONG PROGRAM PAGE SIGNALS
  // -----------------------------------------

  const programSignals = [
    'program',
    'programme',
    'degree',
    'graduate',
    'doctoral',
    'master',
    'phd'
  ];

  if (
    programSignals.some(term =>
      title.includes(term) ||
      url.includes(term)
    )
  ) {
    score += 10;
    reasons.push('program_page_signal');
  }


  // -----------------------------------------
  // DEPARTMENT / SCHOOL SIGNALS
  // -----------------------------------------

  const departmentSignals = [
    'department',
    'school of',
    'faculty of',
    'college of'
  ];

  if (
    departmentSignals.some(term =>
      title.includes(term)
    )
  ) {
    score += 5;
    reasons.push('department_signal');
  }


  // -----------------------------------------
  // NEGATIVE / LOW-VALUE PAGE SIGNALS
  // -----------------------------------------

  const strongNegativeSignals = [
    'summer school',
    'summer_school',
    'summer-school',
    'news',
    'event',
    'conference',
    'workshop'
  ];

  if (
    strongNegativeSignals.some(term =>
      title.includes(term) ||
      url.includes(term)
    )
  ) {
    score -= 35;
    reasons.push('low_value_page_penalty');
  }


  const weakerNegativeSignals = [
    'course',
    'seminar',
    'announcement'
  ];

  if (
    weakerNegativeSignals.some(term =>
      title.includes(term) ||
      url.includes(term)
    )
  ) {
    score -= 15;
    reasons.push('weak_page_penalty');
  }


  // -----------------------------------------
  // SEARCH POSITION BONUS
  // -----------------------------------------

  const position = Number(
    candidate.candidate_position || 999
  );

  if (position === 1) {
    score += 8;
    reasons.push('search_position_1');
  }

  else if (position === 2) {
    score += 5;
    reasons.push('search_position_2');
  }

  else if (position === 3) {
    score += 3;
    reasons.push('search_position_3');
  }


  return {
    score,
    reasons
  };
}


// =============================================
// SCORE ALL CANDIDATES
// =============================================

const ranked = items.map(item => {

  const candidate = item.json;

  const result =
    scoreCandidate(candidate);

  return {
    ...candidate,

    relevance_score:
      result.score,

    ranking_reasons:
      result.reasons
  };
});


// =============================================
// SORT HIGHEST SCORE FIRST
// =============================================

ranked.sort((a, b) => {

  if (
    b.relevance_score !==
    a.relevance_score
  ) {
    return (
      b.relevance_score -
      a.relevance_score
    );
  }

  return (
    Number(a.candidate_position || 999) -
    Number(b.candidate_position || 999)
  );
});


// =============================================
// KEEP TOP 5 ONLY
// =============================================

const topCandidates =
  ranked.slice(0, 5);

const totalRanked =
  topCandidates.length;


// =============================================
// OUTPUT
// =============================================

return topCandidates.map(
  (candidate, index) => ({
    json: {

      ...candidate,

      candidate_rank:
        index + 1,

      ranked_candidate_count:
        totalRanked,

      ranked_candidates_found:
        true,

      ranking_status:
        'success'
    }
  })
);

// =============================================
// 13 — Extract Program Evidence
// n8n 2.35.7
// Preserve ACTUAL scraped page evidence
// =============================================

const response = $input.first().json;

if (!response) {
  throw new Error('Scrape response is missing.');
}

if (response.success !== true) {
  throw new Error('Program candidate scrape was not successful.');
}


// =============================================
// GET SCRAPED CONTENT
// =============================================

const markdown = String(
  response?.data?.markdown || ''
).trim();

const metadata =
  response?.data?.metadata || {};

const rawScrapedUrl = String(
  metadata?.sourceURL ||
  metadata?.url ||
  ''
).trim();

if (!rawScrapedUrl) {
  throw new Error(
    'Scraped page URL is missing from Firecrawl metadata.'
  );
}


// =============================================
// URL NORMALIZER
// =============================================

function normalizeUrl(url) {

  return String(url || '')
    .trim()
    .toLowerCase()
    .split('#')[0]
    .split('?')[0]
    .replace(/^https?:\/\//i, '')
    .replace(/^www\./i, '')
    .replace(/\/+$/, '');
}

const scrapedUrl =
  normalizeUrl(rawScrapedUrl);


// =============================================
// GET RANKED CANDIDATES
// =============================================

const rankedItems =
  $('Rank Program / Department Candidates')
    .all()
    .map(item => item.json);

if (rankedItems.length === 0) {
  throw new Error(
    'Ranked program candidates are missing.'
  );
}


// =============================================
// MATCH ACTUAL SCRAPED CANDIDATE
// =============================================

const candidate =
  rankedItems.find(item =>
    normalizeUrl(item.candidate_url) ===
    scrapedUrl
  );

if (!candidate) {
  throw new Error(
    `Could not match scraped URL to ranked candidate: ${rawScrapedUrl}`
  );
}


// =============================================
// PAGE TITLE
// =============================================

const pageTitle = String(
  metadata?.title ||
  candidate.candidate_title ||
  ''
).trim();


// =============================================
// EXTRACT FIRST H1
// =============================================

let pageH1 = '';

if (markdown) {

  const h1Match =
    markdown.match(/^#\s+(.+)$/m);

  pageH1 =
    h1Match
      ? String(h1Match[1]).trim()
      : '';
}


// =============================================
// FINAL OUTPUT
// =============================================

return [
  {
    json: {

      ...candidate,

      scrape_success:
        true,

      scraped_source_url:
        rawScrapedUrl,

      normalized_scraped_url:
        scrapedUrl,

      candidate_match_status:
        'matched',

      page_title:
        pageTitle,

      page_h1:
        pageH1,

      page_markdown:
        markdown,

      page_character_count:
        markdown.length,

      scraped_status_code:
        Number(
          metadata?.statusCode || 200
        ),

      extraction_status:
        markdown
          ? 'success'
          : 'success_without_markdown'
    }
  }
];

// =============================================
// 14 — Verify Target Field Match
// n8n 2.35.7
// Uses actual scraped page evidence
// =============================================

const data = $json;

const targetField = String(
  data.target_field || ''
)
  .trim()
  .toLowerCase();

if (!targetField) {
  throw new Error(
    'Target field is missing.'
  );
}


// =============================================
// EVIDENCE
// =============================================

const pageTitle = String(
  data.page_title || ''
).toLowerCase();

const pageH1 = String(
  data.page_h1 || ''
).toLowerCase();

const searchTitle = String(
  data.candidate_title || ''
).toLowerCase();

const description = String(
  data.candidate_description || ''
).toLowerCase();

const markdown = String(
  data.page_markdown || ''
).toLowerCase();

const url = String(
  data.candidate_url || ''
).toLowerCase();


// =============================================
// NORMALIZER
// =============================================

function normalize(text) {

  return String(text || '')
    .toLowerCase()
    .replace(/&/g, ' and ')
    .replace(/[-_/]/g, ' ')
    .replace(/[^\p{L}\p{N}\s]/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}


const normalizedTarget =
  normalize(targetField);

const strongText =
  normalize(
    `${pageTitle} ${pageH1} ${searchTitle}`
  );

const bodyText =
  normalize(
    `${description} ${markdown}`
  );


// =============================================
// STRONG MATCH
// =============================================

const exactStrongMatch =
  strongText.includes(
    normalizedTarget
  );


// =============================================
// TOKEN MATCH
// =============================================

const targetTokens =
  normalizedTarget
    .split(' ')
    .filter(word =>
      word.length >= 3
    );

const strongMatchedTokens =
  targetTokens.filter(token =>
    strongText.includes(token)
  );

const strongTokenCoverage =
  targetTokens.length
    ? strongMatchedTokens.length /
      targetTokens.length
    : 0;


// =============================================
// BODY MATCH
// =============================================

const exactBodyMatch =
  bodyText.includes(
    normalizedTarget
  );

let bodyOccurrenceCount = 0;

if (normalizedTarget) {

  let position = 0;

  while (true) {

    const found =
      bodyText.indexOf(
        normalizedTarget,
        position
      );

    if (found === -1) {
      break;
    }

    bodyOccurrenceCount++;

    position =
      found +
      normalizedTarget.length;
  }
}


// =============================================
// KNOWN VARIANTS
// =============================================

const variants = [];

if (
  normalizedTarget ===
  'data science'
) {

  variants.push(
    'master of data science',
    'international master of data science',
    'international master data science',
    'data science and engineering',
    'data science engineering',
    'imds'
  );
}

else if (
  normalizedTarget ===
  'artificial intelligence'
) {

  variants.push(
    'artificial intelligence',
    'machine intelligence',
    'intelligent systems'
  );
}

const variantMatch =
  variants.some(term =>
    strongText.includes(
      normalize(term)
    )
  );


// =============================================
// ACADEMIC CONTEXT
// =============================================

const academicSignals = [
  'program',
  'programme',
  'master',
  'bachelor',
  'phd',
  'doctoral',
  'degree',
  'curriculum',
  'admission',
  'department',
  'school',
  'faculty',
  'center',
  'centre'
];

const academicContext =
  academicSignals.some(signal =>
    (
      strongText +
      ' ' +
      bodyText
    ).includes(signal)
  );


// =============================================
// LOW-VALUE PAGE
//
// Important:
// only strong page areas,
// NOT entire body.
// =============================================

const lowValueText =
  normalize(
    `${pageTitle} ${searchTitle} ${url}`
  );

const lowValueSignals = [
  'summer school',
  'conference',
  'workshop',
  'news',
  'event'
];

const lowValuePage =
  lowValueSignals.some(signal =>
    lowValueText.includes(signal)
  );


// =============================================
// SCORE
// =============================================

let score = 0;

const reasons = [];

if (exactStrongMatch) {

  score += 60;

  reasons.push(
    'target_field_in_title_or_h1'
  );
}

if (variantMatch) {

  score += 45;

  reasons.push(
    'recognized_program_variant'
  );
}

if (strongTokenCoverage === 1) {

  score += 25;

  reasons.push(
    'all_target_tokens_in_strong_area'
  );
}

if (
  exactBodyMatch &&
  bodyOccurrenceCount >= 2
) {

  score += 20;

  reasons.push(
    'repeated_target_field_in_page_content'
  );
}

if (academicContext) {

  score += 10;

  reasons.push(
    'academic_program_context'
  );
}

if (lowValuePage) {

  score -= 50;

  reasons.push(
    'low_value_page_penalty'
  );
}

score = Math.max(
  0,
  Math.min(100, score)
);


// =============================================
// FINAL DECISION
// =============================================

const verified =
  !lowValuePage &&
  academicContext &&
  (
    exactStrongMatch ||
    variantMatch ||
    strongTokenCoverage === 1 ||
    (
      exactBodyMatch &&
      bodyOccurrenceCount >= 2
    )
  );


// =============================================
// OUTPUT
// =============================================

return {
  json: {

    ...data,

    target_field_verified:
      verified,

    target_field_match_score:
      score,

    target_field_match_strength:
      score >= 80
        ? 'high'
        : score >= 55
          ? 'medium'
          : 'low',

    exact_target_match:
      exactStrongMatch,

    recognized_program_variant:
      variantMatch,

    target_token_coverage:
      strongTokenCoverage,

    target_field_body_occurrences:
      bodyOccurrenceCount,

    academic_context_verified:
      academicContext,

    low_value_page:
      lowValuePage,

    target_field_match_reasons:
      reasons,

    target_field_verification_status:
      verified
        ? 'verified'
        : 'not_verified'
  }
};

// =============================================
// 17 — Verify Degree Level
// n8n 2.35.7
// Does NOT require page_markdown
// =============================================

const data = $json;

const requestedRaw = String(
  data.degree_level || ''
).trim().toLowerCase();

const pageTitle = String(
  data.page_title || ''
).toLowerCase();

const pageH1 = String(
  data.page_h1 || ''
).toLowerCase();

const candidateTitle = String(
  data.candidate_title || ''
).toLowerCase();

const description = String(
  data.candidate_description || ''
).toLowerCase();

const markdown = String(
  data.page_markdown || ''
).toLowerCase();

const url = String(
  data.candidate_url ||
  data.program_url ||
  ''
).toLowerCase();


// =============================================
// NORMALIZE DEGREE
// =============================================

let normalizedDegree = requestedRaw;
let requestedAliases = [];
let competingAliases = [];

if (requestedRaw.includes('master')) {

  normalizedDegree = 'master';

  requestedAliases = [
    'master',
    "master's",
    'master of',
    'msc',
    'm.sc',
    'ms program',
    'graduate degree'
  ];

  competingAliases = [
    'bachelor',
    'undergraduate',
    'phd',
    'doctoral',
    'doctorate'
  ];
}

else if (
  requestedRaw.includes('phd') ||
  requestedRaw.includes('doctor')
) {

  normalizedDegree = 'phd';

  requestedAliases = [
    'phd',
    'ph.d',
    'doctoral',
    'doctorate',
    'doctor of philosophy'
  ];

  competingAliases = [
    'bachelor',
    'undergraduate',
    'master',
    'msc'
  ];
}

else if (
  requestedRaw.includes('bachelor')
) {

  normalizedDegree = 'bachelor';

  requestedAliases = [
    'bachelor',
    "bachelor's",
    'bachelor of',
    'undergraduate',
    'bsc',
    'b.sc'
  ];

  competingAliases = [
    'master',
    'msc',
    'phd',
    'doctoral'
  ];
}


// =============================================
// EVIDENCE AREAS
// =============================================

const strongArea = [
  pageTitle,
  pageH1,
  candidateTitle
].join(' ');

const allEvidence = [
  pageTitle,
  pageH1,
  candidateTitle,
  description,
  markdown,
  url
].join(' ');


function containsAny(text, terms) {
  return terms.some(term =>
    text.includes(term)
  );
}


// =============================================
// MATCHES
// =============================================

const degreeInStrongArea =
  containsAny(
    strongArea,
    requestedAliases
  );

const degreeInDescription =
  containsAny(
    description,
    requestedAliases
  );

const degreeInPageContent =
  containsAny(
    markdown,
    requestedAliases
  );

const competingDegreeInStrongArea =
  containsAny(
    strongArea,
    competingAliases
  );


// =============================================
// SCORE
// =============================================

let score = 0;
const reasons = [];

if (degreeInStrongArea) {
  score += 70;
  reasons.push(
    'requested_degree_in_program_title'
  );
}

if (degreeInDescription) {
  score += 20;
  reasons.push(
    'requested_degree_in_search_description'
  );
}

if (degreeInPageContent) {
  score += 10;
  reasons.push(
    'requested_degree_in_page_content'
  );
}

if (
  competingDegreeInStrongArea &&
  !degreeInStrongArea
) {
  score -= 40;
  reasons.push(
    'different_degree_in_program_title'
  );
}

score = Math.max(
  0,
  Math.min(100, score)
);


// =============================================
// FINAL
// =============================================

const degreeVerified =
  degreeInStrongArea ||
  (
    degreeInDescription &&
    !competingDegreeInStrongArea
  );

return {
  json: {
    ...data,

    normalized_degree_level:
      normalizedDegree,

    degree_level_verified:
      degreeVerified,

    degree_level_match_score:
      score,

    degree_level_match_strength:
      score >= 80
        ? 'high'
        : score >= 60
          ? 'medium'
          : 'low',

    degree_in_strong_area:
      degreeInStrongArea,

    degree_in_description:
      degreeInDescription,

    degree_in_page_content:
      degreeInPageContent,

    competing_degree_in_strong_area:
      competingDegreeInStrongArea,

    degree_level_match_reasons:
      reasons,

    degree_level_verification_status:
      degreeVerified
        ? 'verified'
        : 'not_verified'
  }
};

// =============================================
// 22 — Build Faculty Source Search Queries
// n8n 2.35.7
// Purpose:
// Find official Faculty / Staff / People source
// NO program-language verification
// NO scraping
// =============================================

const data = $input.first().json;


// =============================================
// REQUIRED INPUT
// =============================================

const targetField = String(
  data.target_field || ''
).trim();

const country = String(
  data.country || ''
).trim().toLowerCase();

const officialDomain = String(
  data.official_domain || ''
)
  .trim()
  .toLowerCase()
  .replace(/^www\./, '');

if (!targetField) {
  throw new Error(
    'Target field is missing.'
  );
}

if (!officialDomain) {
  throw new Error(
    'Official university domain is missing.'
  );
}


// =============================================
// PROGRAM URL
// =============================================

const programUrl = String(
  data.program_url ||
  data.scraped_source_url ||
  data.candidate_url ||
  ''
).trim();


// =============================================
// BASE FACULTY SEARCHES
//
// Keep only 3 targeted searches.
// No full-site crawl.
// =============================================

const queries = [

  {
    faculty_query_index: 1,

    faculty_query_type:
      'field_faculty',

    faculty_search_query:
      `"${targetField}" faculty professors`
  },

  {
    faculty_query_index: 2,

    faculty_query_type:
      'field_staff',

    faculty_search_query:
      `"${targetField}" academic staff people`
  }

];


// =============================================
// COUNTRY-SPECIFIC LOCALIZED SEARCH
//
// IMPORTANT:
// This is NOT program-language verification.
//
// These words only help discover faculty pages
// on local university websites.
// =============================================

if (country === 'china') {

  let localizedField =
    targetField;

  const field =
    targetField.toLowerCase();

  if (field === 'data science') {
    localizedField = '数据科学';
  }

  else if (
    field === 'computer science'
  ) {
    localizedField = '计算机科学';
  }

  else if (
    field === 'artificial intelligence'
  ) {
    localizedField = '人工智能';
  }

  else if (
    field === 'mathematics'
  ) {
    localizedField = '数学';
  }

  else if (
    field === 'statistics'
  ) {
    localizedField = '统计学';
  }


  queries.push({

    faculty_query_index: 3,

    faculty_query_type:
      'localized_faculty_search',

    faculty_search_query:
      `"${localizedField}" 教师 师资 教授 导师`
  });

}

else {

  queries.push({

    faculty_query_index: 3,

    faculty_query_type:
      'department_faculty',

    faculty_search_query:
      `"${targetField}" department faculty staff`
  });

}


// =============================================
// RETURN 3 N8N ITEMS
// =============================================

return queries.map(query => ({

  json: {

    ...data,

    official_domain:
      officialDomain,

    program_url:
      programUrl,

    ...query
  }

}));

