// =============================================
// 24 — Select Best Faculty Source
// n8n 2.35.7
//
// Purpose:
// Select ONE best official Faculty / Staff
// directory URL from Node 23 search results.
//
// NO program-language verification.
// NO page scraping.
// =============================================


// =============================================
// GET INPUTS
// =============================================

const responses =
  $input.all();

const queryItems =
  $('Build Faculty Source Search Queries')
    .all();

const base =
  queryItems[0]?.json || {};


// =============================================
// BASE DATA
// =============================================

const officialDomain = String(
  base.official_domain || ''
)
  .trim()
  .toLowerCase()
  .replace(/^www\./, '');

const targetField = String(
  base.target_field || ''
)
  .trim()
  .toLowerCase();

if (!officialDomain) {
  throw new Error(
    'Official university domain is missing.'
  );
}


// =============================================
// STORAGE
// =============================================

const candidates = [];

const seenUrls =
  new Set();

let rawFacultyResultCount = 0;


// =============================================
// PROCESS ALL SEARCH RESPONSES
// =============================================

for (
  let responseIndex = 0;
  responseIndex < responses.length;
  responseIndex++
) {

  const response =
    responses[responseIndex]?.json || {};

  const results =
    Array.isArray(
      response?.data?.web
    )
      ? response.data.web
      : [];

  rawFacultyResultCount +=
    results.length;

  const queryInfo =
    queryItems[responseIndex]?.json || {};


  // ===========================================
  // PROCESS EACH SEARCH RESULT
  // ===========================================

  for (const result of results) {

    const rawUrl = String(
      result?.url || ''
    ).trim();

    if (!rawUrl) {
      continue;
    }


    // =========================================
    // EXTRACT HOST
    // =========================================

    const hostMatch =
      rawUrl.match(
        /^https?:\/\/([^\/?#]+)/i
      );

    if (!hostMatch) {
      continue;
    }

    const candidateHost =
      hostMatch[1]
        .toLowerCase()
        .replace(/^www\./, '')
        .split(':')[0];


    // =========================================
    // OFFICIAL DOMAIN CHECK
    // =========================================

    const officialDomainMatch =
      candidateHost === officialDomain ||
      candidateHost.endsWith(
        '.' + officialDomain
      );

    if (!officialDomainMatch) {
      continue;
    }


    // =========================================
    // CLEAN URL
    // =========================================

    const cleanUrl =
      rawUrl
        .split('#')[0]
        .split('?')[0]
        .replace(/\/+$/, '');

    if (!cleanUrl) {
      continue;
    }

    const dedupeKey =
      cleanUrl.toLowerCase();

    if (seenUrls.has(dedupeKey)) {
      continue;
    }

    seenUrls.add(dedupeKey);


    // =========================================
    // RESULT TEXT
    // =========================================

    const title = String(
      result?.title || ''
    ).trim();

    const description = String(
      result?.description || ''
    ).trim();

    const titleLower =
      title.toLowerCase();

    const descriptionLower =
      description.toLowerCase();

    const urlLower =
      cleanUrl.toLowerCase();

    const combined =
      `${titleLower} ${descriptionLower} ${urlLower}`;


    // =========================================
    // SCORE
    // =========================================

    let score = 0;

    const reasons = [];


    // -----------------------------------------
    // TARGET FIELD RELEVANCE
    // -----------------------------------------

    if (
      targetField &&
      titleLower.includes(targetField)
    ) {

      score += 30;

      reasons.push(
        'target_field_in_title'
      );
    }

    else if (
      targetField &&
      descriptionLower.includes(
        targetField
      )
    ) {

      score += 15;

      reasons.push(
        'target_field_in_description'
      );
    }


    // =========================================
    // STRONG FACULTY DIRECTORY SIGNALS
    // =========================================

    const strongFacultySignals = [

      // Common English directory labels
      'faculty members',
      'faculty directory',
      'academic staff',
      'staff directory',
      'faculty',
      'professors',
      'professor',
      'academic team',
      'our people',
      'people',
      'teachers',

      // Common Chinese directory labels
      '教师名录',
      '师资队伍',
      '师资力量',
      '教师队伍',
      '师资',
      '教师',
      '教授',
      '导师'
    ];

    if (
      strongFacultySignals.some(
        signal =>
          combined.includes(signal)
      )
    ) {

      score += 45;

      reasons.push(
        'faculty_directory_signal'
      );
    }


    // =========================================
    // ACADEMIC UNIT SIGNALS
    // =========================================

    const academicUnitSignals = [

      'department',
      'school',
      'college',
      'faculty of',
      'center',
      'centre',
      'institute',

      '学院',
      '系',
      '中心',
      '研究院'
    ];

    if (
      academicUnitSignals.some(
        signal =>
          combined.includes(signal)
      )
    ) {

      score += 10;

      reasons.push(
        'academic_unit_signal'
      );
    }


    // =========================================
    // STRONG URL PATTERNS
    // =========================================

    const facultyUrlSignals = [

      '/faculty',
      '/faculties',
      '/staff',
      '/people',
      '/professor',
      '/professors',
      '/teacher',
      '/teachers',

      // Common Chinese-site abbreviations
      '/jsml',
      '/szdw',
      '/szll',
      '/facultylist'
    ];

    if (
      facultyUrlSignals.some(
        signal =>
          urlLower.includes(signal)
      )
    ) {

      score += 20;

      reasons.push(
        'faculty_url_pattern'
      );
    }


    // =========================================
    // SEARCH QUERY SOURCE BONUS
    // =========================================

    const queryType = String(
      queryInfo.faculty_query_type || ''
    ).toLowerCase();

    if (
      queryType === 'field_faculty'
    ) {

      score += 8;

      reasons.push(
        'primary_faculty_query'
      );
    }

    else if (
      queryType ===
      'localized_faculty_search'
    ) {

      score += 7;

      reasons.push(
        'localized_faculty_query'
      );
    }

    else {

      score += 4;
    }


    // =========================================
    // SEARCH POSITION BONUS
    // =========================================

    const position =
      Number(
        result?.position || 999
      );

    if (position === 1) {

      score += 8;

      reasons.push(
        'search_position_1'
      );
    }

    else if (position === 2) {

      score += 5;

      reasons.push(
        'search_position_2'
      );
    }

    else if (position === 3) {

      score += 3;

      reasons.push(
        'search_position_3'
      );
    }


    // =========================================
    // BAD PAGE PENALTIES
    // =========================================

    const badPageSignals = [

      'news',
      'event',
      'conference',
      'workshop',
      'seminar',
      'announcement',

      'admission',
      'apply now',
      'application',

      'curriculum',
      'course',
      'syllabus',

      'summer school'
    ];

    if (
      badPageSignals.some(
        signal =>
          combined.includes(signal)
      )
    ) {

      score -= 40;

      reasons.push(
        'non_faculty_page_penalty'
      );
    }


    // =========================================
    // INDIVIDUAL PROFILE PENALTY
    //
    // We need listing page,
    // not one professor profile.
    // =========================================

    const individualProfileSignals = [

      'biography',
      'personal homepage',
      'curriculum vitae',
      'research profile',

      '/profile/',
      '/person/',
      '/member/'
    ];

    if (
      individualProfileSignals.some(
        signal =>
          combined.includes(signal)
      )
    ) {

      score -= 30;

      reasons.push(
        'individual_profile_penalty'
      );
    }


    // =========================================
    // PROGRAM/ADMISSION PAGE PENALTY
    // =========================================

    const programPageSignals = [

      'program overview',
      'programme overview',
      'admission requirements',
      'application requirements',
      'degree program'
    ];

    if (
      programPageSignals.some(
        signal =>
          combined.includes(signal)
      )
    ) {

      score -= 20;

      reasons.push(
        'program_page_penalty'
      );
    }


    // =========================================
    // SAVE CANDIDATE
    // =========================================

    candidates.push({

      faculty_source_url:
        cleanUrl,

      faculty_source_title:
        title,

      faculty_source_description:
        description,

      faculty_source_domain:
        candidateHost,

      faculty_source_score:
        score,

      faculty_source_reasons:
        reasons,

      faculty_source_position:
        position,

      discovered_by_faculty_query:
        queryInfo.faculty_search_query ||
        '',

      discovered_by_faculty_query_type:
        queryInfo.faculty_query_type ||
        'unknown'
    });
  }
}


// =============================================
// SORT BEST FIRST
// =============================================

candidates.sort(
  (a, b) => {

    if (
      b.faculty_source_score !==
      a.faculty_source_score
    ) {

      return (
        b.faculty_source_score -
        a.faculty_source_score
      );
    }

    return (
      Number(
        a.faculty_source_position || 999
      ) -
      Number(
        b.faculty_source_position || 999
      )
    );
  }
);


// =============================================
// SELECT BEST
// =============================================

const best =
  candidates[0] || null;


// =============================================
// CONFIDENCE GATE
//
// Because domain is already official,
// 30 is reasonable without another scrape.
// =============================================

const facultySourceFound =
  Boolean(
    best &&
    best.faculty_source_score >= 30
  );


// =============================================
// FINAL OUTPUT
// =============================================

return [
  {
    json: {

      ...base,

      faculty_source_found:
        facultySourceFound,

      faculty_source_url:
        facultySourceFound
          ? best.faculty_source_url
          : '',

      faculty_source_title:
        best?.faculty_source_title ||
        '',

      faculty_source_description:
        best?.faculty_source_description ||
        '',

      faculty_source_score:
        best?.faculty_source_score ||
        0,

      faculty_source_reasons:
        best?.faculty_source_reasons ||
        [],

      faculty_candidate_count:
        candidates.length,

      raw_faculty_result_count:
        rawFacultyResultCount,

      faculty_source_status:
        facultySourceFound
          ? 'verified_candidate_found'
          : 'faculty_source_not_found'
    }
  }
];

// =============================================
// 16 — Prepare Verification Failure Result
// n8n 2.35.7
//
// Handles:
// - Invalid / unverified university
// - Program candidate not found
// - Target field not verified
// - Requested degree not available
// - Faculty source not found
// =============================================

const data = $json;


// =============================================
// ORIGINAL INPUT
// =============================================

let original = {};

try {

  original =
    $('Normalize & Validate Input')
      .first()
      .json || {};

} catch {}


// =============================================
// UNIVERSITY VERIFICATION DATA
// =============================================

let verification = {};

try {

  verification =
    $('Verify Official University Website')
      .first()
      .json || {};

} catch {}

const verificationData =
  verification?.data?.json || {};


// =============================================
// UNIVERSITY NAME
// =============================================

const universityName =
  data.university_name ||
  verificationData.university_name ||
  original.official_domain ||
  data.official_domain ||
  '';


// =============================================
// DETERMINE FAILURE STATUS
// =============================================

let status =
  'Verification failed';


// ---------------------------------------------
// 1. UNIVERSITY WEBSITE FAILURE
// ---------------------------------------------

if (
  verificationData.is_official_university_site === false
) {

  status =
    'Official university website not verified';
}


// ---------------------------------------------
// 2. PROGRAM SEARCH FAILURE
// ---------------------------------------------

else if (
  data.program_candidates_found === false ||
  data.ranked_candidates_found === false
) {

  status =
    'Target program not found';
}


// ---------------------------------------------
// 3. TARGET FIELD FAILURE
// ---------------------------------------------

else if (
  data.target_field_verified === false
) {

  status =
    'Target program not verified';
}


// ---------------------------------------------
// 4. DEGREE FAILURE
// ---------------------------------------------

else if (
  data.degree_level_verified === false
) {

  status =
    'Requested degree not available';
}


// ---------------------------------------------
// 5. FACULTY SOURCE FAILURE
// ---------------------------------------------

else if (
  data.faculty_source_found === false
) {

  status =
    'Faculty source not found';
}


// =============================================
// FINAL 7 COLUMNS
// =============================================

return {
  json: {

    'University Name':
      universityName,

    'Target Field':
      data.target_field ||
      original.target_field ||
      '',

    'Degree':
      data.degree_level ||
      original.degree_level ||
      '',

    'Country':
      data.country ||
      original.country ||
      '',

    'Program URL':
      data.program_url ||
      data.scraped_source_url ||
      data.candidate_url ||
      '',

    'Faculty Source URL':
      data.faculty_source_url ||
      '',

    'Status':
      status
  }
};
